ane"},{"name":"Getsemaní (street art, Plaza de la Trinidad, Café Havana)","si_tag":"culture","tier":"essential","source":"https://www.cartagenaexplorer.com/getsemani-guide/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"walking-tour affiliate + boutique lodging","wells":["eat"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Castillo San Felipe de Barajas","si_tag":"culture","tier":"essential","source":"https://mycartagenatrip.com/things-to-do-in-cartagena/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the largest Spanish fort in South America, on a hill over the city","si":"culture","blurb":"the largest Spanish fort in South America, on a hill over the city","when":"Dec–Mar/Apr","commission":"city-tour affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Minca (coffee/cloud forest, Sierra Nevada)","si_tag":"culture","tier":"essential","source":"https://mytriptocolombia.com/visit-parc-tayrona/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"Santa Marta DMC + eco-lodge affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["DMC","affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ciudad Perdida (Teyuna) 4-day trek","si_tag":"culture","tier":"premier","source":"https://www.kimkim.com/c/the-lost-city-tayrona-park-adventure-10-days","hook":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","si":"culture","blurb":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","commission":"licensed-operator DMC (mandatory)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Barranquilla Carnival","si_tag":"culture","tier":"premier","source":"https://ich.unesco.org/en/RL/carnival-of-barranquilla-00051","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","si":"culture","blurb":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","when":"Dec–Mar/Apr","commission":"event DMC + Barranquilla hotel affiliate (fire ~late-Jan)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["DMC","affiliate","hotel","event"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Mompox (UNESCO colonial river town)","si_tag":"culture","tier":"premier","source":"https://en.wikipedia.org/wiki/Barranquilla_Carnival","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"specialist heritage DMC + boutique lodging","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","romance":"destination","tropical":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"How much does a walled-city wedding in Cartagena cost?","a":"A private-villa wedding for 40–60 guests starts around USD $40,000, including a 2–3-night buyout of a restored colonial casa with pool, rooftop, chef, butler and security. Cartagena''s wedding DMCs assemble venue, villa, catering and logistics as the agent-of-record (~10–20% land).","source":"cartagenadreams.com, 2026-07-07","si_tag":"romance"},{"q":"How do you get to the Rosario Islands and Playa Blanca from Cartagena?","a":"By speedboat — about 1 hour offshore to the Corales del Rosario y San Bernardo National Park for reef snorkeling and a beach-club lunch on Playa Blanca (Barú). Book a licensed day-tour; the ~1-hr open-water return chops up in the windy Dec–Apr season, so tours often head back earlier.","source":"tomplanmytrip.com, 2026-07-07","si_tag":"tropical"},{"q":"What are the must-do sights in Cartagena?","a":"The walled Ciudad Amurallada is the anchor — most visitors need 3–4 days — with Castillo San Felipe de Barajas, the largest Spanish fort in South America, and Getsemaní''s street art and Plaza de la Trinidad salsa nights just outside the walls.","source":"mycartagenatrip.com, 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for in Cartagena?","a":"Scopolamine (\"devil''s breath\") drugging is the headline traveler risk — colourless and tasteless, slipped into drinks or offered items to incapacitate and rob. The US Embassy singled out Cartagena (with Medellín and Bogotá) as a hotspot, often via dating apps. Never accept drinks, food or tabs from strangers, and travel during daylight.","source":"financecolombia.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Cartagena & Colombia''s Caribbean Coast — Walled-City Weddings, Rosario Islands & Tayrona | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-CO","local_keywords":["qué hacer en Cartagena","Islas del Rosario tour","Ciudad Amurallada Cartagena","bodas Cartagena","Parque Tayrona Cabo San Juan","hoteles de lujo Cartagena"],"hreflang":["en","es-CO"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","source_updated":"2026-08-18T15:51:11+01:00"}]},"content_freshness":"2026-07-07","long_tail":["things to do in Cartagena Colombia","Cartagena walled city weddings","Rosario Islands day trip from Cartagena","Tayrona National Park Cabo San Juan guide","is Cartagena safe 2026","Cartagena luxury colonial hotels"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["romance","tropical","culture"],"ultra":[{"name":"Sofitel Legend Santa Clara","type":"17th-c. former monastery, walled city — prestige address","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa Pestagua","type":"18th-c. palace, Relais & Châteaux, Two MICHELIN Keys 2025","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa San Agustín","type":"11-key colonial mansion, Leading Hotels of the World","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Hotel Charleston Santa Teresa","type":"grande-dame walled-city luxury","routing":"preferred-partner + host","tier":"luxury→ultra"},{"name":"Tcherassi Hotel + Spa","type":"designer boutique, restored colonial house","routing":"preferred-partner + host","tier":"luxury"},{"name":"Blue Apple Beach (Barú)","type":"design beach club + villa, Barú island","routing":"villa/MoR + host","tier":"ultra"},{"name":"Walled-city private villas","type":"full colonial-house buyouts, chef/butler/security","routing":"MoR villa + wedding DMC","tier":"ultra"}],"source_verified":null,"hero":{"query":"Cartagena & Colombia''s Caribbean Coast, Colombia"},"geo":{"lat":10.391,"lng":-75.4794},"orbit":[{"id":"san-andres-colombia","jewels":13,"si":["tropical","liveaboard","romance","culture"]}],"orbit_country":["bogota-colombia","medellin-colombia"]}'::jsonb, 2),
  ('akumal-mexico', '10S', 'Akumal', 'Mexico', 'Turtle bay, cenotes and reef', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Akumal means ''place of the turtles'' in Maya; the bay''s seagrass beds feed wild green sea turtles.","A certified guide and life jacket are mandatory to enter the turtle-snorkel area.","No touching turtles (federal offense); keep 3 m distance, 2 min per turtle, biodegradable sunscreen or rashguard only.","Turtle sightings permitted 8am-5pm; sessions cap at ~55 minutes; no fins, no diving on the circuit.","Cenote and reef diving are easily reached, making Akumal a serene dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~25 min north; local clinics stabilize/transfer; major trauma to Cancún","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","turtle_season":"green turtles graze year-round; snorkel 8am-5pm, <=55-min sessions; nesting ~May-Oct overlaps green/sargassum months","sargassum_window":"Apr-Aug (Jun-Jul peak); Akumal affected (seagrass bay, naturally weedy)","fill_the_beds":"sargassum/green months lead with Yal-Ku Lagoon, cenote dives, reef dives, Tulum-ruin loops, turtle morning at opening","fire_date":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; turtle-nesting off-peak push into green season","event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"booking_lead":"peak 3-4 months (villa stock finite, book earlier); shoulder 4-6 months"},"jewels":[{"name":"Guided Akumal Bay turtle snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","bookable_category":"guided snorkel tour","source":"https://absolute-adventure-mexico.com/snorkeling/akumal-bay-regulation-swim-with-the-turtles/","si":"ocean","blurb":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","commission":"Amstar 12% / affiliate; bay + guide fees pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","ocean":"primary"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Yal-Ku Lagoon snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","bookable_category":"snorkel add-on","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"ocean","blurb":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","commission":"affiliate 4-8%; entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"culture":"destination","diveglobal":"evidenced","ocean":"primary"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Akumal-area cenote cavern dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives inland pair the turtle bay with cave country.","bookable_category":"cenote cavern dive (guide required)","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives inland pair the turtle bay with cave country.","when":"Dec-Apr","commission":"DMC 12% / affiliate 4-8%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"culture":"destination","diveglobal":"primary","ocean":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Akumal reef dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Shallow near-shore reef dives with easy multi-dive days.","bookable_category":"reef dive","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Shallow near-shore reef dives with easy multi-dive days.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"culture":"destination","diveglobal":"primary","ocean":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Tulum ruins + turtle-bay combo day","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Maya ruins paired with an Akumal turtle morning.","bookable_category":"guided combo excursion","source":"https://www.embracethejourneytravel.com/agent-portal/vendor-list/amstar/","si":"culture","blurb":"Cliff-top Maya ruins paired with an Akumal turtle morning.","commission":"Amstar 12%; ruin/bay entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","diveglobal":"destination","ocean":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":[],"commission_embedded":false,"commission_basis":"band"}],"faq":[{"q":"What''s the real risk to plan for in Akumal?","a":"Sargassum, water, mosquitoes and hurricanes — not violent crime. 2026 is tracking a record sargassum year, with Akumal affected Apr–Aug (Jun–Jul peak) because the bay is seagrass habitat and naturally weedy by design; drink bottled/purified water only, use repellent for dengue (peak May–November, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Can you swim with wild sea turtles in Akumal, and when''s best?","a":"Yes — it is the whole reason to come, and green turtles graze the bay''s seagrass year-round. Go at 8am opening for the calmest water and fewest boats; snorkeling is permitted only 8am–5pm in sessions capped at ~55 minutes, always with a certified guide over the seagrass beds.","source":"absolute-adventure-mexico.com, 2026-07-04","si_tag":"ocean"},{"q":"Can I dive cenotes and reef from Akumal?","a":"Yes — Akumal makes a serene dive base for both. Guided cenote cavern dives sit just inland (Cenote Azul corridor) and shallow reef dives are close to shore; cavern diving requires a certified cave/cavern guide and stays in the daylight zone. Observe no-fly of 18h single / 24h repetitive; the nearest chamber is ~25 min north in Playa del Carmen.","source":"sssnetwork.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Akumal good for a honeymoon?","a":"Yes, if you want quiet and private over resort buzz. Akumal is villa-driven — beachfront villas with private pools and chef service, plus the wider luxury tier at ~US$400–600+/night in March — and it is calmer and more purposeful than Playa or Tulum. For branded ultra, Rosewood/Banyan Tree at Mayakoba sit ~35–40 min north with an easy turtle-morning day trip.","source":"machupicchu.org / rentalescapes.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Akumal, and when is it cheapest?","a":"Nov–March is the best weather window; the cheapest is the green season, June–mid-October. Peak Dec–Apr brings the best conditions and highest rates; May–June and November shoulders run ~30–40% off with thinner crowds; the green season is hot, rainy and cheapest but carries hurricane exposure (Jun–Nov).","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"tropical"},{"q":"Can I visit Maya ruins from Akumal?","a":"Yes — Akumal pairs a turtle morning with cliff-top Maya ruins in a single day. Tulum''s ruins are a short drive south and Cobá is inland; a common loop is ruins at 8–10am then the turtle bay after, bookable as a guided combo excursion.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"}],"seo":{"meta_title":"Akumal Travel Guide 2026 — Swim with Sea Turtles Responsibly | TravelWell.World","meta_description":"Plan Akumal, ''place of the turtles'': guided no-touch turtle snorkeling rules, cenote & reef diving, straight 2026 sargassum, safety and nearest dive-chamber contacts.","slug":"akumal-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["nadar con tortugas en Akumal","reglas nadar con tortugas Akumal 2026","snorkel en Akumal","buceo en cenotes Akumal","mejor época para ver tortugas en Akumal","sargazo Akumal 2026","Laguna Yal-Ku Akumal","villas frente al mar Akumal"],"hreflang":["en","es-MX"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Akumal beachfront luxury villas","price_tier":"ultra","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"no branded ultra hotel in-village; top villa tier","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/akumal"},{"name":"Rosewood Mayakoba (~35-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Akumal, Mexico"},"geo":{"lat":20.3958,"lng":-87.3153},"orbit":[{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico"