ossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dry season Nov-Apr (calm-water AM); Dec-Apr hardest to book, Jan/Mar busiest","shoulder":"Nov and Feb-Mar (best value in dry window; avoid Semana Santa)","green":"Rainy Jun-Sep (afternoon showers, hurricane overlap) - fill-the-beds","fill_the_beds":"Jun-Sep green + Nov/early-Dec shoulder; sell slow-travel/wellness (yoga, dawn paddle)","source":"https://hellobacalar.com/guides/best-time-visit-bacalar","fire_date":"Live ~4-6 months ahead of Nov-Apr (by ~Jun-Jul); secondary green-season value push for Jun-Sep","event_peaks":"Semana Santa (domestic crush), Dec holiday + New Year","booking_lead":"Longer than regional avg for dock-front/lagoon-front; best waterfront stock clears first for Dec-Apr"},"jewels":[{"name":"Los Rapidos + Canal de los Piratas sailboat circuit","si_tag":"tropical","status":"live","tier":"comfort","bookable_category":"lagoon tour","source":"https://www.thoroughlytravel.com/bacalar-lagoon/","hook":"half-day sail across the color bands past the pirate channel ·","si":"tropical","blurb":"half-day sail across the color bands past the pirate channel ·","commission":"affiliate ~4-8% (Viator/GYG) or lodge direct","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"adventure":"destination","tropical":"primary","wellness":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Cenote Azul open-air swim","si_tag":"tropical","status":"live","tier":"essential","bookable_category":"cenote entry","source":"https://kendyltravels.com/bacalar-cenotes/","hook":"~70 m-wide, ~90 m-deep sky cenote with rim restaurant ·","si":"tropical","blurb":"~70 m-wide, ~90 m-deep sky cenote with rim restaurant ·","commission":"non-commissionable gate; bundle into day-tour","wells":["eat"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"adventure":"destination","tropical":"primary","wellness":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Negro (seventh color)","si_tag":"tropical","status":"live","tier":"comfort","bookable_category":"lagoon tour","source":"https://kendyltravels.com/bacalar-cenotes/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the deep-blue cenote said to complete the seven colors ·","si":"tropical","blurb":"the deep-blue cenote said to complete the seven colors ·","when":"Dry season Nov-Apr","commission":"affiliate via tour","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"adventure":"destination","tropical":"primary","wellness":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Stromatolite kayak (Cenote Cocalitos)","si_tag":"globaladv","status":"future","tier":"comfort","bookable_category":"guided eco-tour","source":"https://sandinmycurls.com/bacalar-mexico-seven-color-lagoon-guide/","si":"adventure","commission":"guided-tour affiliate; no-touch/no-sunscreen mandatory","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","tropical":"destination","wellness":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Eco-luxury lagoon lodge (Habitas / Boca de Agua)","si_tag":"wellness","status":"future","tier":"luxury","bookable_category":"boutique lodging","source":"https://www.bocadeagua.com/blog/best-hotels-bacalar-mexico","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"thatched cabins, yoga, clear kayaks, lagoon-front restaurant ·","si":"wellness","blurb":"thatched cabins, yoga, clear kayaks, lagoon-front restaurant ·","when":"Dry season Nov-Apr","commission":"on application, 10%+ boutique/luxury","wells":["stay","eat","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical","wellness"],"shelf_fit":{"adventure":"destination","tropical":"evidenced","wellness":"primary"},"commission_pct_low":10,"commission_pct_high":10,"commission_lane":[],"commission_embedded":false,"commission_basis":"band"},{"name":"Sunrise kayak + slow-water day","si_tag":"wellness","status":"future","tier":"comfort","bookable_category":"lodge activity","source":"https://www.bocadeagua.com/","si":"wellness","commission":"bundled in lodge rate","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["wellness"],"shelf_fit":{"adventure":"destination","tropical":"destination","wellness":"primary"},"commission_lane":["bundle","hotel"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for in Bacalar?","a":"Open-water swimming discipline, mosquitoes and hurricanes - not crime. Cenote Azul is a sky-facing sinkhole up to ~90m deep with no floor, so treat it as open water (strong swimmers/life vests); use repellent for dengue (present, worse in the rainy season); hurricane season runs Jun-Nov, peaking Aug-Oct.","source":"kendyltravels.com","si_tag":"safety"},{"q":"Is swimming allowed near the stromatolites?","a":"Yes to swimming the lagoon, but the stromatolites are strictly no-touch and no-sunscreen. Do not touch, stand on, or apply regular sunscreen near the colonies - a single handprint can destroy years of microbial growth - so view and photograph from a kayak only, using biodegradable sunscreen or none. Bacalar is not a scuba destination, so there are no dive or no-fly considerations.","source":"sandinmycurls.com","si_tag":"globaladv"},{"q":"What is the Lagoon of Seven Colors, and how do you see it?","a":"It''s a karst-fed freshwater lagoon whose colors shift from turquoise to navy over its sand, cenotes and varying depths. The signature way to see it is a half-day catamaran or sailboat circuit past Los Rapidos, the stromatolites and the Canal de los Piratas; go on a calm morning when the water is glass-still.","source":"thoroughlytravel.com","si_tag":"tropical"},{"q":"Which are the best eco-luxury places to stay in Bacalar?","a":"Boca de Agua and Our Habitas Bacalar lead the lagoon. Boca de Agua is a Frida Escobedo-designed set of ~26 stilted treehouse villas on 82 acres with a MICHELIN Key 2025; Our Habitas is the established adults-only, wellness-led lagoon retreat ~20 min south of town. Both are direct/consortia bookings - book waterfront stock early for Dec-Apr.","source":"mrandmrssmith.com","si_tag":"wellness"},{"q":"When is the best time to visit Bacalar?","a":"November-April, the dry season, is best - warm, mostly dry, with glass-still calm-water mornings. Within that, November and Feb-March are the best value (avoid Semana Santa); the rainy green season, Jun-Sep, is lush, quiet and cheapest but brings afternoon showers and hurricane overlap.","source":"hellobacalar.com","si_tag":"tropical"}],"seo":{"meta_title":"Bacalar Mexico: Lagoon of Seven Colors & Stromatolites","meta_description":"Bacalar''s Lagoon of Seven Colors, living stromatolites and open-air cenotes - where to sail, swim and stay, and how to protect what you came to see.","slug":"bacalar-mexico","primary_keyword":"Bacalar Lagoon of Seven Colors","long_tail":["Bacalar stromatolites","Cenote Azul Bacalar","Bacalar eco lodges","Bacalar sailboat tour","Bacalar things to do"],"search_language":"bilingual (en + es-MX)","local_keywords":["Laguna de los Siete Colores","Bacalar que hacer","estromatolitos Bacalar","Cenote Azul Bacalar","hoteles Bacalar laguna","tour velero Bacalar","mejor epoca para visitar Bacalar"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"codes":[],"note":"the real planning is open-water swim discipline + stromatolite protection + hurricane season, not crime; MXN currency","advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":5,"misses":17,"disregarded":3,"note":"Canonical 25-SI list; FRESHWATER lagoon - Dive Globally is a MISS (no scuba/cenote-cert node here, unlike Cozumel/Chinchorro); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"wellness","name":"wellness","status":"future"},{"si":"globaladv","name":"adventure","status":"future"}],"ultra":[{"name":"Boca de Agua","price_tier":"ultra","what":"Frida Escobedo-designed eco-luxury, ~26 stilted treehouse villas on 82 acres, MICHELIN Key 2025","bookable":"direct + Mr & Mrs Smith (Hyatt) + MICHELIN Guide Hotels","earning":"on application / host-Virtuoso-or-Smith consortia","mor_posture":"broker to property/consortia; property-paid commission; no net-rate resale","direct_only_flag":false,"source":"https://www.mrandmrssmith.com/luxury-hotels/boca-de-agua"},{"name":"Our Habitas Bacalar","price_tier":"luxury-ultra","what":"Most established luxe-eco resort; adults-only, lagoon A-frame tents + jungle rooms, holistic wellness/spa","bookable":"direct + Mr & Mrs Smith + Ownia Collection","earning":"on application / host-consortia","mor_posture":"broker to property/consortia; property-paid commission","direct_only_flag":false,"source":"https://www.ourhabitas.com/bacalar/"}],"source_verified":"2026-07-04","hero":{"query":"Bacalar, Mexico"},"geo":{"lat":18.6767,"lng":-88.3953},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico","jewels":5,"si":["romance","expedition","diveglobal","culture"]},{"id":"puerto-aventuras-mexico","jewels":5,"si":["romance","diveglobal","ocean","wildlife"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adven