  ('balandra-beach-mexico', '10S', 'Balandra Beach (Playa Balandra)', 'Mexico', 'Balandra beach La Paz', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"tropical","family","romance"}', '{"tropical"}', '{"essential","comfort","premier"}', null, 'core', '{"key_facts":["CONANP Natural Protected Area since 2008; ~25 km north of La Paz","Two fixed daily shifts (08:00-12:00 / 13:00-17:00), ~450 visitors per slot, first-come","Conservation bracelet required ~MXN 125 pp/day (under-12s, seniors/retirees, disabilities exempt with ID)","No commercial food service inside the bay; limited services (toilets/info) - bring own water/shade/snacks","El Hongo mushroom rock is the emblem of Balandra and La Paz; shallow calm turquoise water"],"safety":{"emergency":"911","hospital":"limited on-site (toilets/info only); serious cases ~25 km to La Paz - Hospital Salvatierra/ISSSTE/private + air-evac; carry medical insurance","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"carry own bottled/purified water - no services in the bay","hurricane":"Jun-Nov - trip insurance for summer/fall","day_use":"TIMED-ENTRY two shifts + ~450/slot cap, first-come, arrive >=30 min early; CONANP bracelet required; NO food vendors inside","sun_heat":"scarce shade - umbrella, hat, reef-safe sunscreen, ample water","el_hongo":"protected/restored rock - do not climb or touch","swimming":"shallow, calm, family-safe but NO lifeguards - supervise children, watch outgoing tide; no diving (wading/kayak beach)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-