ard visitor cap","sources":["https://www.thoroughlytravel.com/balandra-beach-mexico/","https://beachythings.site/playa-balandra-entrance-fee-rules/","https://mrplayas.com/la-paz/beaches"],"fire_date":"add-on jewel, not standalone - market inside La Paz/Baja campaigns (Nov-Apr beach campaigns late summer; summer value in spring), always paired with La Paz lodging + transfer","event_peaks":"Christmas-New Year, Semana Santa (Easter), Mexican summer holidays - domestic surges hit slot cap hardest","booking_lead":"no lodging to pre-book; conservation bracelet is same-day/short-lead (CONANP digital or La Paz office); binding constraint is daily slot cap (~450/shift) - plan day, arrive early; book La Paz lodging on 3-6-month peak lead"},"jewels":[{"name":"El Hongo mushroom-rock walk + swim","si_tag":"tropical","status":"live","tier":"essential","bookable":"beach-day tour/transfer + CONANP bracelet or self-drive","source":"https://en.wikipedia.org/wiki/Puerto_Balandra,_Baja_California_Sur","hook":"wade the shallow flats to Baja''s most-photographed rock, the emblem of La Paz","si":"tropical","blurb":"wade the shallow flats to Baja''s most-photographed rock, the emblem of La Paz","commission":"DMC transfer + Viator/GYG affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"family":"destination","romance":"destination","tropical":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Kayak / SUP the turquoise flats","si_tag":"tropical","status":"live","tier":"comfort","bookable":"local kayak/SUP rental/tour","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","hook":"paddle glass-calm, waist-deep water around the coves; low-impact, all-ages","si":"tropical","blurb":"paddle glass-calm, waist-deep water around the coves; low-impact, all-ages","commission":"operator + GYG affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["tropical"],"shelf_fit":{"family":"destination","romance":"destination","tropical":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Shallow-water kids'' beach day","si_tag":"family","status":"future","tier":"essential","bookable":"beach-day transfer + bracelet","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","hook":"near-waveless, waist-deep flats — one of Baja''s gentlest child-friendly swims","si":"family","blurb":"near-waveless, waist-deep flats — one of Baja''s gentlest child-friendly swims","commission":"DMC transfer + affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["family","tropical"],"shelf_fit":{"family":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Balandra + Tecolote combo day","si_tag":"family","status":"future","tier":"comfort","bookable":"combined beach-day tour","source":"https://mrplayas.com/la-paz/beaches","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"pair protected Balandra with nearby Playa Tecolote for a full family beach day","si":"family","blurb":"pair protected Balandra with nearby Playa Tecolote for a full family beach day","when":"Nov-Apr","commission":"local operator + Viator affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["family","tropical"],"shelf_fit":{"family":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sunrise/early-slot photo morning","si_tag":"romance","status":"future","tier":"premier","bookable":"private driver-guide + bracelet","source":"https://www.thoroughlytravel.com/balandra-beach-mexico/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"postcard turquoise + El Hongo before the crowds and heat — couples'' shoot backdrop","si":"romance","blurb":"postcard turquoise + El Hongo before the crowds and heat — couples'' shoot backdrop","when":"Nov-Apr","commission":"Journey Mexico/Amstar DMC + affiliate","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance","tropical"],"shelf_fit":{"family":"destination","romance":"primary","tropical":"evidenced"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"How do I get into Balandra, and what does it cost?","a":"Arrive at least 30 minutes before your shift and buy a conservation bracelet — Balandra is not a walk-up-anytime beach. Entry runs in two fixed daily slots (08:00–12:00, 13:00–17:00), capped near 450 visitors each on a first-come basis, with a ~MXN 125 pp/day CONANP bracelet (exemptions for under-12s, seniors and people with disabilities).","source":"thoroughlytravel.com","si_tag":"tropical"},{"q":"When is the best time for photos at El Hongo?","a":"Take the 08:00 morning slot in the cooler Nov–Apr months for the best light and the emptiest sand. Balandra fills its ~450-per-slot cap fastest in peak season and over Mexican holidays, and midday desert glare flattens the turquoise — so the early shift gives couples both the calm water and the postcard color.","source":"thoroughlytravel.com","si_tag":"romance"},{"q":"What''s the real risk to plan for at Balandra?","a":"Sun, heat and the lack of services — not crime. There is scarce shade, no food or water vendors and no lifeguards inside the bay, and hurricane season runs Jun–Nov; bring an umbrella, hydration and reef-safe sunscreen, and carry trip insurance for summer/fall dates.","source":"dossier","si_tag":"safety"}],"seo":{"meta_title":"Balandra Beach La Paz: El Hongo & Entry Rules 2026","meta_description":"Wade the shallow turquoise flats of protected Playa Balandra to El Hongo mushroom rock — timed entry (~450/slot), conservation bracelet, no services. Plan the day.","slug":"balandra-beach-mexico","primary_keyword":"Balandra beach La Paz","long_tail":["Balandra beach entrance fee 2026","Playa Balandra timed entry rules","El Hongo mushroom rock La Paz","Balandra vs Tecolote beach","Balandra shallow water family beach"],"search_language":["en","es-MX"],"local_keywords":["Playa Balandra La Paz horarios","brazalete Balandra CONANP precio","El Hongo de Balandra","playa protegida La Paz aguas someras","Balandra vs Tecolote","Playa Balandra niños familia","cómo llegar a Balandra La Paz"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"codes":[],"note":"MXN currency, USD widely accepted","advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":3,"misses":19,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"family","name":"family","status":"future","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"future","t