-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 8),
  ('banos-ecuador', '10S', 'Baños de Agua Santa, Ecuador', 'Ecuador', 'Baños de Agua Santa', 'live', 'verified', 'mountainValley', 'Andes (Quito) & Galápagos', '{"wellness","romance"}', '{}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","book_enabled":true,"air_access_verified":"No airport in Baños — access via UIO (Mariscal Sucre, Quito) + ~3-3.5 hr road transfer (~180 km)","altitude_m":1820,"altitude_notes":{"banos_m":1820,"casa_del_arbol_runtun_m":2600,"mild_ams":"uncommon at town level (1,820m); watch if arriving from Quito 2,850m or higher paramo; exertion at 2,600m viewpoints is real work","trauma":"Local hospital for stabilization; serious trauma routes to Ambato (~40 min) then Quito (~3-3.5 hr); complex cases evac to US (Miami)"},"volcano":{"name":"Tungurahua","type":"active stratovolcano (~5,023m)","status_2026":"background / very-low IG-EPN alert; no eruption activity; 24/7 monitoring; UNESCO Geopark (2025)","history":"near-continuous eruption 1999-2016, quiet since 2016","rule":"Re-verify live IG-EPN status before each booking; know town ashfall/lahar evacuation routes","monitoring_source":"https://www.igepn.edu.ec/tungurahua"},"water":"not reliably potable — bottled/filtered (distinct from thermal-bath waters, for soaking not drinking)","advisory_source":"https://www.gov.uk/foreign-travel-advice/ecuador","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/ecuador","read":"2026-08-20T14:53:32Z","page_updated":"2026-07-10T10:44:44+01:00","source_country":"ecuador","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The Coastal Region provinces of Esmeraldas, Manabí, Santa Elena, Guayas, El Oro, Los Ríos and Santo Domingo de los Tsáchilas","lvl":3,"posture":"all-but-essential","except":["airside transit within Guayaquil Airport"],"note":"Gang-related violence linked to organised crime; the city of Guayaquil is inside this restriction."},{"name":"Within 20km of the Ecuador-Colombia border","lvl":3,"posture":"all-but-essential","except":["the El Ángel Ecological Reserve","the Rumichaca border crossing","the town of Tulcán","the Pan-American Highway (in Carchi province)"]}]},"timing":{"peak":["Sep","Oct","Nov","Dec","Jan","Feb"],"shoulder_green":["Mar","Apr","May","Jun","Jul","Aug"],"inflection":["Aug","Feb","Mar"],"fire_date":"curve-start minus 1-2 weeks (mid-Aug for the Sep-Feb dry peak; 1-2 weeks ahead of Ecuadorian holiday weekends/Carnaval/Semana Santa); fire against the arriving Quito curve when Baños rides as an Andes/Amazon attach","events":["Ecuadorian national holiday weekends (feriados) — domestic-demand spikes","Carnaval (Feb-Mar)","Semana Santa"],"rafting_note":"Pastaza Class III+ year-round; Class IV seasonal (~Aug-May)"},"jewels":[{"name":"Casa del Árbol — Swing at the End of the World","si_tag":"expedition","tier":"essential","source":"https://www.viator.com/Banos-attractions/Casa-del-Arbol-Swing/d22150-a19710","timing":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the iconic treehouse swing on the Runtún ridge, launching out over the Tungurahua gorge; entry ~$1, 07:00–19:00, harness-secured, 18+","si":"expedition","blurb":"the iconic treehouse swing on the Runtún ridge, launching out over the Tungurahua gorge; entry ~$1, 07:00–19:00, harness-secured, 18+","when":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","commission":"Guided swing/viewpoint tour affiliate or DMC leg (entry non-commissionable)","wells":["stay"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Pailón del Diablo (Devil''s Cauldron waterfall)","si_tag":"expedition","tier":"essential","source":"https://www.zoegoesplaces.com/cascada-el-pailon-del-diablo-ecuador/","timing":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"is one of Ecuador''s most dramatic waterfalls — roughly 80 m tall with a plunge pool ~20 m deep","si":"expedition","blurb":"is one of Ecuador''s most dramatic waterfalls — roughly 80 m tall with a plunge pool ~20 m deep","when":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","commission":"Ruta de las Cascadas day-trip affiliate/DMC (trail entry non-comm.)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ruta de las Cascadas (bike / chiva)","si_tag":"expedition","tier":"essential","source":"https://southamericabackpacker.com/ruta-de-las-cascadas-banos/","hook":"~16 km of seven waterfalls downhill from Baños along the Pastaza","si":"expedition","blurb":"~16 km of seven waterfalls downhill from Baños along the Pastaza","commission":"Bike-hire + guided-route/chiva-tour affiliate (fall/cable fees non-comm.)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Canyoning — Río Blanco","si_tag":"expedition","tier":"comfort","source":"https://www.geotoursbanios.com/","timing":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","commission":"Local adventure-operator booking (Geotours/Ivagatours) — guided-only","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["operator","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Whitewater rafting — Río Pastaza (Class III-IV)","si_tag":"expedition","tier":"essential","source":"https://www.viator.com/Banos-tours/White-Water-Rafting/d22150-g17-c27534","timing":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"half-day guided runs; Class III+ year-round, Class IV seasonal; PFD + helmet + river guide","si":"expedition","blurb":"half-day guided runs; Class III+ year-round, Class IV seasonal; PFD + helmet + river guide","when":"[''Sep'', ''Oct'', ''Nov'', ''Dec'', ''Jan'', ''Feb'']","commission":"Local operator + activity affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","romance":"destination","wellness":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Mirador Bellavista","si_tag":"expedition","tier":"essential","source":"https://www.ecuatouring.com/banos-travel-guide/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"a short, steep hike for the postcard panorama of Baños in its gorge with Tungurahua behind — a free, romantic sunset jewel","si":"expedition","blurb":"a short, steep hike for the postcard panorama of Baños in its gorge with Tungurahua behind — a free, romantic sunset jewel","when":"year-round","commission":"Guided town-and-viewpoint walk affiliate or self-guided add-on","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","romance"],"shelf_fit":{"expedition":"primary","romance":"evidenced","wellness":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Termas de la Virgen thermal baths (at night)","si_tag":"romance","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g312857-d20120113-Reviews-Termas_de_la_Virgen-Banos_Tungurahua_Province.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"soak in Tungurahua-heated, sulfate-rich mineral pools in the town center, beneath the floodlit Cabellera de la Virgen waterfall; open into the evening, ~$4 entry","si":"romance","blurb":"soak in Tungurahua-heated, sulfate-rich mineral pools in the town center, beneath the floodlit Cabellera de la Virgen waterfall; open into the evening, ~$4 entry","when":"year-round","commission":"Entry non-commissionable — monetize spa-hotel room-night + private spa add-on","wells":["stay","beauty"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","wellness"],"shelf_fit":{"romance":"primary","wellness":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Luna Volcán / former Luna Runtún — spa with volcano view","si_tag":"romance","tier":"luxury","source":"https://www.booking.com/hotel/ec/luna-volcan-adventure-spa.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"perched on Tungurahua''s flank on 35 ha of Andean forest, infinity pool over the valley, themed suites; the marquee romantic-adventure perch above Baños","si":"romance","blurb":"perched on Tungurahua''s flank on 35 ha of Andean forest, infinity pool over the valley, themed suites; the marquee romantic-adventure perch above Baños","when":"year-round","commission":"Direct/luxury-specialist + bedbank; property/wing buyout for weddings","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","wellness"],"shelf_fit":{"romance":"primary","wellness":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Samari Spa Resort (converted monastery)","si_tag":"wellness","tier":"luxury","source":"https://www.luxurylatinamerica.com/ecuador/samari.html","timing":"year-round","timing_type":"ALWAYS-ON","si":"wellness","when":"year-round","commission":"Direct/luxury-specialist + bedbank — future Wellness SI anchor","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wellness"],"shelf_fit":{"romance":"destination","wellness":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"Is the \"Swing at the End of the World\" worth it — and how much?","a":"Yes, and it is cheap — it is the image that put Baños on a million screens. The Casa del Árbol treehouse swing launches you out over the Tungurahua gorge from the Runtún ridge at ~2,600 m; the complex opens 07:00–19:00, entry is ~$1, and staff clip you into a climbing harness on a steel-beam frame.","source":"viator.com, 2026-07-07","si_tag":"expedition"},{"q":"Where can couples soak in thermal baths at night in Baños?","a":"At the Termas de la Virgen, in the town center beneath the floodlit Cabellera de la Virgen waterfall. Its sulfate-rich pools are heated by Tungurahua, open 05:00–17:00 and again 18:00–22:00, at ~$4 adult entry — the signature romantic-and-restorative Baños ritual, best paired with a volcano-view spa-hotel room-night.","source":"tripadvisor.com, 2026-07-07","si_tag":"romance"},{"q":"Is Baños a genuine wellness and spa destination?","a":"Increasingly, yes — the town''s name literally means \"Baths of Holy Water.\" The anchor is Samari Spa Resort, a 300-year-old former Jesuit monastery on ~10 acres with a heated indoor pool, sauna, Turkish bath, whirlpool and full spa, ranked among Baños''s top hotels — mineral-rich thermal springs fed by Tungurahua''s volcanic heat make Baños a natural wellness base.","source":"luxurylatinamerica.com, 2026-07-07","si_tag":"wellness-—-future-si"},{"q":"What''s the real risk to plan for in Baños?","a":"Not urban crime — the load-bearing risk is activity risk. ~88% of Ecuador''s homicides occur in five coastal provinces, and the Andean highlands including Baños run below the homicide rates of many mid-sized US cities; the town''s core product is adrenaline (canyoning, Class III–IV rafting, the swing, highway cycling), so guided-vs-unguided is the whole game.","source":"myecuadorvisa.com, 2026-07-07","si_tag":"safety"},{"q":"Is the Tungurahua volcano dangerous right now?","a":"It is a real, live geohazard held quiet by monitoring — not a decorative caveat. Tungurahua erupted near-continuously 1999–2016, then went quiet; as of mid-2026 IG-EPN reports background/very-low activity with no precursor signals and 24/7 instrument monitoring, so any escalation would trigger alerts well in advance. Re-verify live IG-EPN status before booking.","source":"igepn.edu.ec, 2026-07-07","si_tag":"safety"},{"q":"Is canyoning or the swing in Baños dangerous?","a":"Both carry real, activity-specific risk that guiding and gear mitigate. Canyoning on the Río Blanco is a guided-only roped waterfall-descent sport (helmet, harness, wetsuit, certified guide); the Casa del Árbol swing is 18+ with a ~220 lb (100 kg) weight limit and requires the operator''s climbing harness every ride. Never freelance either — book reputable operators like Geotours or Ivagatours.","source":"geotoursbanios.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Baños de Agua Santa, Ecuador — The Swing, Waterfalls, Rafting & Thermal Baths | TravelWell","jsonld_type":"TouristDestination","search_language":"es-EC","local_keywords":["qué hacer en Baños Ecuador","Casa del Árbol columpio","columpio fin del mundo Baños","Pailón del Diablo","Ruta de las Cascadas","rafting río Pastaza Baños","canyoning Baños","Termas de la Virgen","volcán Tungurahua estado","hoteles con spa en Baños"],"hreflang":["en","es-EC"],"primary_keyword":"Baños de Agua Santa","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/ecuador","read":"2026-08-20T14:53:32Z","source_updated":"2026-07-10T10:44:44+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"wellness","status":"live"},{"si":"romance","status":"live"}],"ultra":[{"name":"Luna Volcán, Adventure SPA (formerly Luna Runtún)","category":"Boutique adventure-spa on Tungurahua''s flank, 30 rooms, 35-ha forest","mor":"Luxury-specialist / direct trade + bedbank; Fora/host-agency on direct","tier":"luxury"},{"name":"Samari Spa Resort","category":"300-yr converted-monastery spa resort, ~10 acres","mor":"Luxury-specialist / direct trade + bedbank; host-agency/Fora on direct","tier":"luxury"},{"name":"Casa del Suizo","category":"Amazon-edge Napo River jungle lodge (Ahuano), 75 rooms","mor":"DMC package / luxury-specialist — the Amazon-extend upsell","tier":"$$$-$$$$"}],"source_verified":null,"hero":{"query":"Baños de Agua Santa, Ecuador, Ecuador"},"geo":{"lat":-1.3928,"lng":-78.4269},"orbit":[{"id":"cuenca-ecuador","jewels":10,"si":["culture"]},{"id":"galapagos-islands-ecuador","jewels":12,"si":["liveaboard","expedition"]},{"id":"quito-ecuador","jewels":11,"si":["culture"]}],"orbit_country":[]}'::jsonb, 9),
  ('blue-hole-belize', '10S', 'The Belize Atolls & Blue Hole', 'Belize', 'Atolls, walls and the Blue Hole', 'live', 'verified', 'oceanAerial', 'Belize', '{"liveaboard","expedition","tropical"}', '{"tropical"}', '{"comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Great Blue Hole is 318 m (1,043 ft) across and 124 m (407 ft) deep, near the center of Lighthouse Reef ~70 km (43 mi) off Belize City.","Belize has three coral atolls — Turneffe, Lighthouse Reef, Glover''s Reef — within the UNESCO-listed Belize Barrier Reef Reserve System.","Blue Hole stalactites hang at ~100-140 ft (30-42 m); the dive reaches ~40 m/130 ft with a narrow no-deco window — Advanced cert recommended.","Belize Aggressor III/IV depart Belize City Saturdays, up to 5 dives/day, 24-27 dives on a 7-night charter (39-42 on 10-night).","Whale sharks gather at Gladden Spit (southern Belize) around the full moon March-June."],"safety":{"emergency":"911","marine_vhf":"Channel 16","hyperbaric_chamber":"Belize Chamber Project Ltd, San Pedro (Ambergris Caye) — only DAN-Preferred chamber in Belize, 24/7; hours of boat+air transit from the offshore atolls","advisory_date":"2026-06-18","advisory_codes":"C (Crime) only","book_enabled":true,"l3_disclosure":true,"stay_in_zone":true,"air_access_verified":true,"no_fly_after_diving":"12h single no-deco dive / 18h multi-day repetitive / 24h recommended buffer before BZE flight home","water":"open Caribbean ocean; no malaria offshore; high sun/sea exposure; DAN dive insurance with evac coverage effectively mandatory","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-08-20T14:53:57Z","page_updated":"2026-06-12T10:40:30+01:00","source_country":"belize","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"type":"dive-calendar","dive_calendar":true,"curve_start":"2026-02-15","peak":"March-June (Blue Hole best flat s