ies"],"wells_basis":"derived from name/blurb/hook","si_all":["Dive Liveaboards/Tropical Islands","diveglobal","liveaboard","tropical"],"shelf_fit":{"Dive Liveaboards/Tropical Islands":"evidenced","diveglobal":"evidenced","expedition":"destination","liveaboard":"primary","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Dive Liveaboards/Tropical Islands","si_map_basis":"normalised from free text ''Dive Liveaboards/Tropical Islands'' by gen_normalise_jewel_si"},{"name":"The Painted Wall & Quebrada (Lighthouse Reef)","si_tag":"liveaboard","tier":"premier","source":"https://www.aggressor.com/kbyg_document/Belize","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"March-June","commission":"own-CLIA liveaboard lane","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["liveaboard","tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"primary","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Turneffe Elbow (Turneffe Atoll)","si_tag":"Dive Liveaboards/GEA","tier":"comfort","source":"https://www.divessi.com/en/mydiveguide/divesite/98293","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"March-June","commission":"own-CLIA liveaboard lane or Fora via Turneffe resorts","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Dive Liveaboards/GEA","diveglobal","expedition","liveaboard","tropical"],"shelf_fit":{"Dive Liveaboards/GEA":"evidenced","diveglobal":"evidenced","expedition":"evidenced","liveaboard":"primary","tropical":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Dive Liveaboards/GEA","si_map_basis":"normalised from free text ''Dive Liveaboards/GEA'' by gen_normalise_jewel_si"},{"name":"Glover''s Reef (remote atoll)","si_tag":"Dive Liveaboards/GEA","tier":"premier","source":"https://www.belizeadventure.ca/atolls-of-belize/","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"March-June","commission":"own-CLIA liveaboard lane (scarcity — few boats reach it)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["Dive Liveaboards/GEA","diveglobal","expedition","liveaboard","tropical"],"shelf_fit":{"Dive Liveaboards/GEA":"evidenced","diveglobal":"evidenced","expedition":"evidenced","liveaboard":"primary","tropical":"evidenced"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Dive Liveaboards/GEA","si_map_basis":"normalised from free text ''Dive Liveaboards/GEA'' by gen_normalise_jewel_si"},{"name":"Gladden Spit whale sharks (seasonal, southern Belize)","si_tag":"GEA/Dive Liveaboards","tier":"comfort","source":"https://belizescuba.com/diving-snorkeling/whale-sharks/","si":"liveaboard","commission":"AFF/day-operator or Fora via Placencia; marine-reserve fee non-commissionable","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["GEA/Dive Liveaboards","diveglobal","expedition","liveaboard"],"shelf_fit":{"GEA/Dive Liveaboards":"evidenced","diveglobal":"evidenced","expedition":"evidenced","liveaboard":"primary","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane","si_raw":"GEA/Dive Liveaboards","si_map_basis":"normalised from free text ''GEA/Dive Liveaboards'' by gen_normalise_jewel_si"},{"name":"Tobacco Caye","si_tag":"tropical","tier":"comfort","source":"https://www.belizeadventure.ca/atolls-of-belize/","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"March-June","commission":"Fora lane (small guesthouse packages)","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["tropical"],"shelf_fit":{"expedition":"destination","liveaboard":"destination","tropical":"primary"},"commission_lane":["package"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Long Caye (Lighthouse Reef)","si_tag":"Tropical Islands/Dive Liveaboards","tier":"comfort","source":"https://www.belizehighcommission.com/areas-of-belize/lighthouse-reef-bz","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"March-June","commission":"Fora / own-CLIA depending on operator","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["Tropical Islands/Dive Liveaboards","diveglobal","liveaboard","tropical"],"shelf_fit":{"Tropical Islands/Dive Liveaboards":"evidenced","diveglobal":"evidenced","expedition":"destination","liveaboard":"primary","tropical":"evidenced"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical Islands/Dive Liveaboards","si_map_basis":"normalised from free text ''Tropical Islands/Dive Liveaboards'' by gen_normalise_jewel_si"}],"faq":[{"q":"How many dives do you get on a Belize Aggressor liveaboard trip?","a":"Up to five dives a day — 24–27 dives on a 7-night charter, 39–42 on a 10-night. The Aggressor III/IV depart the Fort George dock in Belize City every Saturday at 6 pm, dive Sunday morning to Friday noon, and reach all three atolls, so the liveaboard converts a long day-boat run into unlimited access to Lighthouse Reef, Turneffe and Glover''s.","source":"aggressor.com, 2026-07-06","si_tag":"liveaboard"},{"q":"How deep is the Great Blue Hole dive and do you need to be certified?","a":"The dive reaches ~40 m/130 ft — at or beyond the recreational limit — to see the stalactites that hang between roughly 100–140 ft. Bottom time is measured in minutes and nitrogen narcosis is a real factor, so reputable operators strongly recommend or require Advanced Open Water certification. It is a deliberately deep dive, not a beginner novelty.","source":"dive-the-world.com, 2026-07-06","si_tag":"expedition"},{"q":"What is there to do on the Belize atolls if you don''t dive?","a":"The atoll cayes carry barefoot reef-island character for surface-interval and non-diver days. Tobacco Caye is a few-acre reef caye with snorkel-off-the-dock access; Half Moon Caye is a natural monument with ~4,000 nesting red-footed boobies and an observation tower; Long Caye is the inhabited base camp for Blue Hole and Half Moon Caye dives.","source":"belizeadventure.ca, 2026-07-06","si_tag":"tropical"},{"q":"What''s the real risk to plan for on an atoll dive trip?","a":"Offshore remoteness from the chamber. The only DAN-Preferred recompression chamber in Belize is on San Pedro, Ambergris Caye — hours of boat-then-air transit from a hit at Lighthouse Reef (~70 km/43 mi offshore) or Glover''s. Liveaboards carry onboard O2 and run DAN protocols as first response, which is why depth and deco discipline are non-negotiable and DAN insurance with evacuation coverage is effectively mandatory.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"How long do you have to wait to fly after diving the Blue Hole?","a":"Plan an 18–24 hour buffer. DAN guidance sets a minimum 12-hour surface interval after a single no-deco dive and a minimum 18 hours after multi-day repetitive diving, which every liveaboard trip is; 24 hours is the recommended general practice. A 7-night Aggressor charter ends diving Friday around noon for a Saturday departure precisely to give that buffer before the BZE flight home.","source":"dan.org, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Great Blue Hole & Belize Atolls Diving — Liveaboard, Lighthouse Reef, Turneffe & Glover''s | TravelWell.World","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Belize Blue Hole liveaboard","diving Lighthouse Reef Belize","Belize Aggressor","Great Blue Hole dive depth","Turneffe Atoll diving","Glover''s Reef liveaboard","Half Moon Caye Wall dive","Belize whale shark diving Gladden Spit","no fly after diving Belize"],"hreflang":["en"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/belize","read":"2026-08-20T14:53:57Z","source_updated":"2026-06-12T10:40:30+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["liveaboard","expedition","tropical"],"ultra":[{"name":"Private full-boat liveaboard charter (Belize Aggressor III/IV buyout)","tier":"ultra","mor":"own-CLIA / TCI Land Agency lane — convertible affiliate->commissioned-agent (the moat)","source":"https://www.aggressor.com/destination/belize"},{"name":"Turneffe Island Resort (luxury all-inclusive dive)","tier":"luxury-ultra","mor":"Fora lane (host-agency IATA) all-inclusive dive package","source":"https://visitturneffe.org/discover/where-to-stay-on-turneffe-atoll/"},{"name":"Gladden Private Island (adjacent, southern Belize)","tier":"ultra","mor":"Fora / own-CLIA depending on channel","source":"https://www.belizeadventure.ca/atolls-of-belize/"}],"source_verified":"2026-07-06","hero":{"query":"The Belize Atolls & Blue Hole, Belize"},"geo":{"lat":17.3158,"lng":-87.5346},"orbit":[{"id":"ambergris-caye-belize","jewels":11,"si":["tropical","liveaboard","romance","expedition"]},{"id":"caye-caulker-belize","jewels":9,"si":["tropical","liveaboard","expedition","ocean","culinary"]},{"id":"hopkins-belize","jewels":8,"si":["tropical","expedition","culture"]},{"id":"placencia-belize","jewels":8,"si":["liveaboard","expedition","diveglobal","ocean","wildlife","culture"]},{"id":"san-ignacio-belize","jewels":13,"si":["expedition","culture","romance"]}],"orbit_country":[]}'::jsonb, 10),
