  ('bogota-colombia', '10S', 'Bogotá & The Andes, Colombia', 'Colombia', 'Andean capital, paramo on its doorstep', 'live', 'verified', 'venice', 'Bogotá & The Andes', '{"romance","adventure","culture","culinary"}', '{}', '{"essential","premier","luxury","ultra"}', null, null, '{"key_facts":["Bogotá sits at ~2,640 m (8,660 ft) — one of the highest capital cities on earth; expect mild soroche (altitude effects) for 24–48 hrs on arrival.","The Gold Museum (Museo del Oro) holds ~55,000 pre-Columbian gold pieces, incl. the Muisca raft of the El Dorado legend.","Monserrate rises to 3,152 m over the city, reached by funicular, cable car or a steep daytime walk, with the Basilica at the summit.","Zipaquirá Salt Cathedral is a cathedral carved inside a working salt mine ~1.5–2 hrs from the city; Villa de Leyva has Colombia''s largest cobbled plaza (14,000 m²) and a Cretaceous fossil valley.","Bogotá''s driest, clearest windows are Dec–Mar and Jul–Aug; the biennial Ibero-American Theatre Festival returns August 2026."],"safety":{"emergency":"123","hospital":"Bogotá top private clinics (stabilization); serious cases route to US medical evacuation — evac-grade insurance advised","book_enabled":true,"risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine/''devil''s breath''), extortion, express kidnapping occur throughout Colombia incl. cities","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported","N":"Natural Disaster — earthquake, landslide (advisory names Bogotá for landslide risk)"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"bogota_in_named_danger":false,"air_access_verified":"BOG (El Dorado Intl) — direct international incl. major US, EU and LatAm gateways; Colombia''s primary hub","altitude_m":2640,"altitude_note":"~2,640 m — mild AMS possible 24–48 hrs; Monserrate 3,152 m and páramo hikes 3,200 m+ add load","water":"Bogotá tap generally potable (meets WHO standards per EAAB/Ministry of Health); caveat aging plumbing in older buildings — bottled is conservative default","disease_note":"dengue LOW at altitude (vector scarce above ~1,800 m); rises for low-altitude excursions","scopolamine_caution":"''devil''s breath''/burundanga drugging — colourless/tasteless; Bogotá hotspot (1,409 cases 2023, Chapinero/Teusaquillo/Santa Fe); never accept drinks/food/tabs from strangers; dating-app method documented","personal_safety":"vetted taxi/ride-app only; no wealth display; zone discipline (La Candelaria daytime); do not resist a robbery","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","page_updated":"2026-08-18T15:51:11+01:00","source_country":"colombia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"all of Norte de Santander Department, including Cúcuta","lvl":3,"posture":"all-but-essential"},{"name":"all of Arauca Department","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Puerto Carreño in Vichada Department","lvl":3,"posture":"all-but-essential"},{"name":"within 5km of the rest of the border with Venezuela","lvl":3,"posture":"all-but-essential","note":"The FCDO separately advises against all travel to Venezuela''s side of the border — do not use any Colombia-Venezuela land crossing."},{"name":"Chocó Department","lvl":3,"posture":"all-but-essential","except":["the department capital Quibdó","the towns of Nuquí and Bahía Solano","Capurganá"]},{"name":"the western part of Valle del Cauca Department, including Buenaventura","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Jamundí, Valle del Cauca","lvl":3,"posture":"a