rary","off_season_specials":"dry low-season tail + wet-but-workable shoulder → flexible/budget/photography travelers"},"jewels":[{"name":"Rio da Prata float","si_tag":"expedition","tier":"comfort","source":"https://www.tripadvisor.com/ShowUserReviews-g303368-d1936985-r118728253-Rio_da_Prata-State_of_Mato_Grosso_do_Sul.html","si":"expedition","commission":"DMC/AOR → licensed-agency voucher","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wildlife":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Rio Sucuri snorkel","si_tag":"expedition","tier":"essential","source":"https://www.aventuradobrasil.com/blog/bonito-brazils-natural-gem-of-crystal-clear-rivers-and-hidden-caves/","hook":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","si":"expedition","blurb":"Described as one of the clearest rivers on Earth; emerald underwater gardens threaded with pearl-like oxygen bubbles. Gentler/shorter than Prata, superb clarity","commission":"licensed-agency voucher via AOR","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","wildlife":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Abismo Anhumas rappel + underground-lake dive/snorkel","si_tag":"expedition","tier":"premier","source":"https://www.explore-share.com/trip/abismo-anhumas-abseiling-underground-lake-bonito/","hook":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","si":"expedition","blurb":"72 m descent into a cavern lake with submerged limestone cones up to ~20 m; snorkel or scuba the lake; ~18°C water","commission":"AOR → operator via licensed agency","wells":["activities"],"we