-staffed ultra villa buyout + superyacht/jet charter","why_ultra":"private-estate + LUX cross-cut (NetJets/VistaJet jet-to-yacht)","earning":"villa-agency/charter commission on application (no net-rate resale)","virtuoso_value_add":"attach Virtuoso hotel pre/post-stay","mor":"clean agent-side; red-flag villa-inventory mark-up","price_tier":"ultra"}],"source_verified":"2026-07-04","hero":{"query":"Cabo San Lucas, Mexico"},"geo":{"lat":22.8905,"lng":-109.9167},"orbit":[{"id":"balandra-beach-mexico","jewels":5,"si":["tropical","family","romance"]},{"id":"cabo-pulmo-mexico","jewels":5,"si":["expedition","diveglobal"]},{"id":"east-cape-mexico","jewels":7,"si":["romance","expedition","diveglobal","ocean"]},{"id":"espiritu-santo-island-mexico","jewels":5,"si":["expedition","ocean"]},{"id":"la-paz-mexico","jewels":6,"si":["expedition","tropical","diveglobal"]},{"id":"loreto-mexico","jewels":7,"si":["expedition","tropical","diveglobal","romance"]},{"id":"los-barriles-mexico","jewels":8,"si":["ocean","expedition","tropical"]},{"id":"magdalena-bay-mexico","jewels":5,"si":["expedition","ocean"]},{"id":"san-jose-del-cabo-mexico","jewels":5,"si":["romance","expedition","culture","ocean"]},{"id":"todos-santos-mexico","jewels":6,"si":["expedition","culture","wellness","ocean"]}],"orbit_country":["akumal-mexico","bacalar-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","ensenada-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-miguel-de-allende-mexic