":"https://careyes.com/"}],"source_verified":"2026-07-04","hero":{"query":"Careyes (Costa Careyes), Mexico"},"geo":{"lat":19.4,"lng":-105.03},"orbit":[{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture","senior"]},{"id":"costalegre-mexico","jewels":7,"si":["tropical","romance","ultra","ocean"]},{"id":"guadalajara-mexico","jewels":8,"si":["culture","culinary","entertainment","sports"]},{"id":"mazamitla-mexico","jewels":6,"si":["expedition","family","adventure"]},{"id":"puerto-vallarta-mexico","jewels":5,"si":["romance","expedition","ocean"]},{"id":"san-sebastian-del-oeste-mexico","jewels":6,"si":["culture","expedition","culinary"]},{"id":"tlaquepaque-mexico","jewels":4,"si":["culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","celestun-mexico","chichen-itza-mexico","coba-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 21),
